using System.Text.Json;
using EasyMenu.IntegrationTests.Infrastructure;
using FluentAssertions;
using YamlDotNet.RepresentationModel;

namespace EasyMenu.IntegrationTests.Contract;

/// <summary>
/// Constitution II: the exposed API must match contracts/openapi.yaml.
/// Compares the set of "METHOD /path" operations of the contract with the document generated by the API.
/// </summary>
public sealed class OpenApiContractTests(EasyMenuApiFactory factory) : IntegrationTestBase(factory)
{
    private static readonly HashSet<string> HttpMethods =
        ["get", "put", "post", "delete", "options", "head", "patch", "trace"];

    [Fact]
    public async Task Exposed_operations_match_the_contract()
    {
        var contractOperations = ReadContractOperations();

        var json = await Client.GetStringAsync("/openapi/v1.json");
        var generatedOperations = ReadGeneratedOperations(json);

        generatedOperations.Should().BeEquivalentTo(contractOperations,
            "every endpoint must be described in contracts/openapi.yaml and every contract operation must be implemented");
    }

    private static HashSet<string> ReadContractOperations()
    {
        var yaml = new YamlStream();
        using (var reader = File.OpenText(FindContractFile()))
        {
            yaml.Load(reader);
        }

        var root = (YamlMappingNode)yaml.Documents[0].RootNode;
        var paths = (YamlMappingNode)root.Children[new YamlScalarNode("paths")];

        return paths.Children
            .SelectMany(path => ((YamlMappingNode)path.Value).Children.Keys
                .Select(k => ((YamlScalarNode)k).Value!)
                .Where(HttpMethods.Contains)
                .Select(method => Operation(method, ((YamlScalarNode)path.Key).Value!)))
            .ToHashSet();
    }

    private static HashSet<string> ReadGeneratedOperations(string json)
    {
        using var doc = JsonDocument.Parse(json);
        return doc.RootElement.GetProperty("paths").EnumerateObject()
            .SelectMany(path => path.Value.EnumerateObject()
                .Select(p => p.Name)
                .Where(HttpMethods.Contains)
                .Select(method => Operation(method, path.Name)))
            .ToHashSet();
    }

    private static string Operation(string method, string path) => $"{method.ToUpperInvariant()} {path}";

    private static string FindContractFile()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            var candidate = Path.Combine(dir.FullName, "contracts", "openapi.yaml");
            if (File.Exists(candidate))
            {
                return candidate;
            }
        }

        throw new FileNotFoundException("contracts/openapi.yaml not found in any parent directory.");
    }
}
